		public float OnReleaseHold() {
			if (longStartNote == null)
			{
				ContestUtils.EmitLog("Can not tap LongEnd", LogType.Error);
				return 0.0f;
			}

			DeactiveHoldFx();
			longStartNote.Deactive();
